self.addEventListener('install', (e) => {
  self.skipWaiting();
  e.waitUntil(caches.open(CACHE).then((c) => Promise.all(PRECACHE.map((u) => c.add(new Request(u, { cache: 'reload' })).catch(() => { })))));
});

self.addEventListener('activate', (e) => {
  // v19.2d: the previous version's cache is kept (only older ones go), so a page still running it keeps getting its own
  // files from it, never this version's (textures are addressed by a hash of their bytes: assets/x.webp?h=...)
  e.waitUntil(caches.keys()
    .then((keys) => { const old = keys.filter((k) => k.startsWith('m67-') && k !== CACHE && k !== CARS); return Promise.all(old.slice(0, -1).map((k) => caches.delete(k))); })
    .then(() => self.clients.claim()));
});

self.addEventListener('message', (e) => {
  if (e.data === 'm67-cache-status') caches.open(CACHE).then((c) => c.keys()).then((ks) => e.source && e.source.postMessage({ t: 'm67-cache', build: BUILD, have: ks.length, want: PRECACHE.length }));
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const root = new URL('./', self.registration.scope).pathname;
  // v16.0 Build my car: the site's functions go straight to the network (never kept), except a finished car's shape
  // (api/car/geo, which never changes): kept in its own cache so your car still drives offline
  if (url.pathname.startsWith(root + 'api/')) {
    if (url.pathname === root + 'api/car/geo' && /^[a-z2-7]{16}$/.test(url.searchParams.get('id') || '')) e.respondWith((async () => {
      const c = await caches.open(CARS), hit = await c.match(req);
      if (hit) return hit;
      const r = await fetch(req);
      if (r.status === 200 && (r.headers.get('content-type') || '').includes('application/json')) c.put(req, r.clone());
      return r;
    })());
    return;
  }
  if (req.mode === 'navigate' && (url.pathname === root || url.pathname === root + 'index.html')) {   // (the game's page only: not e.g. preview.jpg opened on its own)
    e.respondWith((async () => {
      const c = await caches.open(CACHE);
      try {
        const net = await Promise.race([fetch(req), new Promise((_, rej) => setTimeout(() => rej(new Error('slow network')), 4000))]);
        if (net.ok) c.put('./', net.clone());
        return net;
      } catch (err) {
        return (await c.match('./')) || (await caches.match('./')) || Response.error();
      }
    })());
    return;
  }
  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    const hit = (await c.match(req)) || (await caches.match(req)); // (this version's copy, else the previous version's: exactly this address)
    if (hit) return hit;
    try {
      const r = await fetch(req);
      if (r.status === 200) c.put(req, r.clone());
      return r;
    } catch (err) {
      const loose = await caches.match(req, { ignoreSearch: true });
      if (loose) return loose;
      throw err;
    }
  })());
});
